namespace RassAppControleFin.Api.Identity;

internal static class PasswordResetPage
{
    // The token remains in the browser URL and is submitted only over HTTPS to this API.
    public const string Html = """
        <!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
        <title>Redefinir senha | RASS Controle Financeiro</title><style>body{font-family:system-ui,sans-serif;background:#f6f7fb;color:#172b4d;margin:0;padding:24px}main{max-width:420px;margin:8vh auto;background:#fff;padding:28px;border:1px solid #d8dee9;border-radius:8px}label,input,button{display:block;width:100%;box-sizing:border-box}input{padding:12px;margin:8px 0 18px;border:1px solid #718096;border-radius:6px}button{padding:12px;background:#001b3d;color:#fff;border:0;border-radius:6px;font-weight:700}#message{margin-top:16px}</style></head><body><main><h1>Nova senha</h1><p>Escolha uma senha entre 8 e 128 caracteres.</p><form id="form"><label for="password">Nova senha</label><input id="password" type="password" minlength="8" maxlength="128" required autocomplete="new-password"><label for="confirm">Confirmar nova senha</label><input id="confirm" type="password" minlength="8" maxlength="128" required autocomplete="new-password"><button>Redefinir senha</button></form><p id="message" role="status"></p></main><script>const m=document.getElementById('message'),t=new URLSearchParams(location.search).get('token');document.getElementById('form').addEventListener('submit',async e=>{e.preventDefault();const p=document.getElementById('password').value,c=document.getElementById('confirm').value;if(!t){m.textContent='Este link e invalido ou expirou.';return}if(p!==c){m.textContent='As senhas nao coincidem.';return}const r=await fetch(location.pathname,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:t,newPassword:p})});const b=await r.json().catch(()=>null);m.textContent=r.ok&&b&&b.success?'Senha redefinida. Volte ao aplicativo para entrar.':'Nao foi possivel redefinir a senha. Solicite um novo link.';if(r.ok&&b&&b.success)e.target.reset()})</script></body></html>
        """;
}
